from build import *
AF_CODES={'42731','I4891','I480','I4892','42732','I482','I481','42789'}
FLUT={'I4892','42732'}
out=open('dossier.txt','w')
for pid,p in P.items():
    dead=p.get('deceasedDateTime')
    out.write('#'*90+'\n')
    out.write(f"PATIENT {pid} mrn={p['identifier'][0]['value']} {p['gender']} dob={p['birthDate']} age={age(pid)} deceased={dead}\n")
    # AF conditions
    afs=[]
    for c in C[pid]:
        for cd in c['code']['coding']:
            if cd['code'] in AF_CODES:
                afs.append((edate(c.get('encounter',{}).get('reference','').split('/')[-1]), cd['code'], cd['display'], c['id']))
    afs.sort(key=lambda x:(x[0] or ''))
    if afs:
        out.write("AF CONDITIONS:\n")
        for a in afs: out.write('  %s %s %s %s\n'%a)
    # ECGs
    if ECG[pid]:
        out.write("ECGS: "+', '.join(f"{x['ecg']}@{x['time']}" for x in ECG[pid])+'\n')
    # current clinic meds
    cur=[]
    for m in MR[pid]:
        vp=m.get('dispenseRequest',{}).get('validityPeriod',{})
        if vp.get('start') and vp.get('end') and vp['start'][:10]<=EVALD<=vp['end'][:10]:
            cur.append(m)
    if cur:
        out.write("CURRENT ORDERS:\n")
        for m in sorted(cur,key=lambda m:m['authoredOn']):
            di=m.get('dosageInstruction',[{}])[0]
            freq=di.get('timing',{}).get('code',{}).get('coding',[{}])[0].get('code')
            out.write(f"  {medname(m)} | {di.get('text')} | {freq} | {m['status']} | {m['dispenseRequest']['validityPeriod']['start'][:10]}->{m['dispenseRequest']['validityPeriod']['end'][:10]} | authored {m['authoredOn'][:10]} | cc={is_cc(m.get('encounter',{}).get('reference','').split('/')[-1])} | {m['id']}\n")
    # all clinic orders 2025+
    hist=[m for m in MR[pid] if m['authoredOn']>'2025-06-01' and is_cc(m.get('encounter',{}).get('reference','').split('/')[-1])]
    if hist:
        out.write("CLINIC ORDERS since 2025-06:\n")
        for m in sorted(hist,key=lambda m:m['authoredOn']):
            di=m.get('dosageInstruction',[{}])[0]
            vp=m['dispenseRequest']['validityPeriod']
            out.write(f"  {m['authoredOn'][:10]} {medname(m)} | {di.get('text')} | {m['status']} | {vp['start'][:10]}->{vp['end'][:10]} | {m['id']}\n")
    # labs since 2026
    labs=[o for o in OB[pid] if o.get('effectiveDateTime','')>'2025-06-01']
    if labs:
        out.write("LABS since 2025-06:\n")
        for o in sorted(labs,key=lambda o:o['effectiveDateTime']):
            v=o.get('valueQuantity',{})
            out.write(f"  {o['effectiveDateTime'][:16]} {o['code']['coding'][0]['display']} = {v.get('value')} {v.get('unit','')} | {o['id']}\n")
    # notes
    ns=sorted(DR[pid],key=lambda d:d['date'])
    if ns:
        out.write("NOTES:\n")
        for d in ns:
            out.write(f"  --- {d['date'][:16]} [{role(d)}] {d['type']['coding'][0]['display']} {d['id']}\n")
            for line in notetext(d).split('\n'):
                out.write('      '+line+'\n')
out.close()
print('done')
